#include <stdio.h>
#include <string.h>

#define HEADER_SIZE 10

typedef struct {
    char key[50];
    char value[100];
} HeaderEntry;

typedef struct {
    HeaderEntry entries[HEADER_SIZE];
    int count;
} HeaderDict;

void test_store_info_in_header() {
    HeaderDict header = { .count = 0 };
    const char *info_type = "lang";
    const char *info_content = "en-US";

    // Call the function to store information
    HeaderDict *updated_header = store_info_in_header(info_type, info_content, &header);

    // Check if the header was updated correctly
    assert(updated_header->count == 1);
    assert(strcmp(updated_header->entries[0].key, "Accept-Language") == 0);
    assert(strcmp(updated_header->entries[0].value, "en-US") == 0);

    printf("Test passed: Header updated correctly.\n");
}

int main() {
    test_store_info_in_header();
    return 0;
}

